                <p class="display-3 @(_lowStockCount > 0 ? "text-danger" : "text-success")">
                    @_lowStockCount
                </p>
                <p class="card-text text-muted">
                    Items below minimum level
                </p>
                <small class="text-muted">Auto-refreshes every 10 seconds</small>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-header">Activity Log</div>
            <div class="card-body">
                <ul class="list-group list-group-flush">
                    @foreach (var entry in _activityLog.TakeLast(10).Reverse())
                    {
                        <li class="list-group-item py-1">
                            <small class="text-muted">@entry.Time.ToString("HH:mm:ss")</small>
