    {
        _lowStockCount = AlertService.LastLowStockCount;
        _activityLog.Add(new LogEntry(DateTime.Now,
            $"Polled {WarehouseState.CurrentWarehouseName}: {_lowStockCount} low-stock item(s)"));
        await InvokeAsync(StateHasChanged);
    }

    private async void OnWarehouseChanged()
    {
        _activityLog.Add(new LogEntry(DateTime.Now,
            $"Switched to {WarehouseState.CurrentWarehouseName}"));
        await AlertService.RefreshNowAsync();
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
        AlertService.StopPolling();
    }

    private record LogEntry(DateTime Time, string Message);
}

